package com.annu.companion;

import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import android.webkit.*;import androidx.webkit.WebViewAssetLoader;

public class FloatingService extends Service{
private static final String CHANNEL="annu_companion";private android.content.SharedPreferences prefs;private WindowManager wm;private WebView avatar;private WindowManager.LayoutParams params;private WebViewAssetLoader assets;private int visibleWidth=180,visibleHeight=220;
@Override public void onCreate(){super.onCreate();prefs=getSharedPreferences("annu",MODE_PRIVATE);NotificationChannel c=new NotificationChannel(CHANNEL,"ANNU companion",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);startForeground(41,notification());if(Settings.canDrawOverlays(this))showAvatar();else stopSelf();}
private Notification notification(){Intent open=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent stop=new Intent(this,FloatingService.class).setAction("STOP");PendingIntent sp=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("ANNU is floating").setContentText("3D companion is on screen").setContentIntent(pi).setOngoing(true).addAction(android.R.drawable.ic_media_pause,"Stop",sp).build();}
private void showAvatar(){assets=AnnuWebAssets.create(this);wm=(WindowManager)getSystemService(WINDOW_SERVICE);avatar=new WebView(this);WebSettings s=avatar.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);avatar.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return assets.shouldInterceptRequest(r.getUrl());}});avatar.setWebChromeClient(new WebChromeClient());avatar.setBackgroundColor(0);avatar.setLayerType(View.LAYER_TYPE_HARDWARE,null);int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;visibleWidth=prefs.getInt("avatar_width",180);visibleHeight=prefs.getInt("avatar_height",220);params=new WindowManager.LayoutParams(visibleWidth,visibleHeight,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.START;params.x=prefs.getInt("avatar_x",12);params.y=prefs.getInt("avatar_y",180);avatar.setOnTouchListener(new View.OnTouchListener(){int x,y;float sx,sy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){x=params.x;y=params.y;sx=e.getRawX();sy=e.getRawY();return true;}if(e.getAction()==2){params.x=x+(int)(e.getRawX()-sx);params.y=y+(int)(e.getRawY()-sy);wm.updateViewLayout(avatar,params);return true;}if(e.getAction()==1){if(Math.abs(e.getRawX()-sx)<12&&Math.abs(e.getRawY()-sy)<12){Intent i=new Intent(FloatingService.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}else{prefs.edit().putInt("avatar_x",params.x).putInt("avatar_y",params.y).apply();}return true;}return true;}});wm.addView(avatar,params);avatar.loadUrl("https://appassets.androidplatform.net/assets/annu.html?floating=1");}
private void resizeAvatar(int w,int h){if(params==null||avatar==null)return;visibleWidth=w;visibleHeight=h;params.width=w;params.height=h;try{wm.updateViewLayout(avatar,params);prefs.edit().putInt("avatar_width",w).putInt("avatar_height",h).apply();}catch(Exception ignored){}}
private void visible(boolean v){if(avatar==null)return;try{params.width=v?visibleWidth:0;params.height=v?visibleHeight:0;wm.updateViewLayout(avatar,params);}catch(Exception ignored){}}
@Override public int onStartCommand(Intent i,int f,int id){if(i!=null){if("STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if("HIDE".equals(i.getAction()))visible(false);if("SHOW".equals(i.getAction()))visible(true);if("SIZE_SMALL".equals(i.getAction()))resizeAvatar(140,175);if("SIZE_LARGE".equals(i.getAction()))resizeAvatar(220,270);if("SIZE_RESET".equals(i.getAction())){params.x=12;params.y=180;prefs.edit().putInt("avatar_x",12).putInt("avatar_y",180).apply();resizeAvatar(180,220);}}return START_STICKY;}
@Override public void onDestroy(){if(wm!=null&&avatar!=null)try{wm.removeView(avatar);}catch(Exception ignored){}if(avatar!=null)avatar.destroy();super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}